import React, { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Button,
    CircularProgress,
    Alert
} from '@mui/material';
import axios from 'axios';
import { useAuth } from './AuthContext';

const InspectorAssignedWork = () => { 
    const [workOrders, setWorkOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const { user } = useAuth();

    useEffect(() => {
        const fetchWorkOrders = async () => {
            if (!user) return;

            try {
                setLoading(true);
                setError(null);

                const response = await axios.get(`http://localhost:8080/workorders/inspector`, {
                    params: { inspectorUsername: user.username }
                });

                const sortedOrders = response.data.sort(
                    (a, b) => new Date(b.assignedDate) - new Date(a.assignedDate)
                );

                setWorkOrders(sortedOrders);
            } catch (error) {
                console.error('Error fetching work orders:', error);
                setError('Failed to load your assigned work. Please try again later.');
            } finally {
                setLoading(false);
            }
        };

        fetchWorkOrders();
    }, [user]);

    const handleDownload = async (id) => {
        try {
            const response = await axios.get(`http://localhost:8080/workorders/download/${id}`, {
                responseType: 'blob'
            });

            const url = window.URL.createObjectURL(new Blob([response.data]));
            const link = document.createElement('a');
            link.href = url;
            link.setAttribute('download', `WorkOrder_${id}.pdf`);
            document.body.appendChild(link);
            link.click();
            link.remove(); // Clean up
        } catch (error) {
            console.error('Error downloading file:', error);
            setError('Unable to download the file. Please try again later.');
        }
    };

    // Group work orders by date
    const groupedWorkOrders = workOrders.reduce((groups, order) => {
        const date = order.assignedDate;
        if (!groups[date]) {
            groups[date] = [];
        }
        groups[date].push(order);
        return groups;
    }, {});

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%' }}>
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return (
            <Box sx={{ padding: 3 }}>
                <Alert severity="error">{error}</Alert>
            </Box>
        );
    }

    if (Object.keys(groupedWorkOrders).length === 0) {
        return (
            <Box sx={{ padding: 3, textAlign: 'center' }}>
                <Typography variant="h4" gutterBottom>Assigned Work</Typography>
                <Typography variant="body1">
                    You don't have any assigned work at the moment.
                </Typography>
            </Box>
        );
    }

    return (
        <Box sx={{ padding: 3, overflowY: 'auto', height: '100%' }}>
            <Typography
                variant="h4"
                gutterBottom
                sx={{ textAlign: 'center', marginBottom: 4 }} 
            >
                Assigned Work
            </Typography>

            {Object.keys(groupedWorkOrders).map((date) => (
                <Box key={date} sx={{ marginBottom: 5 }}>
                    <Typography variant="h6" sx={{ marginBottom: 2 }}>
                        {new Date(date).toLocaleDateString()}
                    </Typography>

                    <Box sx={{
                        display: 'flex',
                        overflowX: 'auto',
                        gap: 2,
                        paddingBottom: 1,
                        '&::-webkit-scrollbar': {
                            height: '8px',
                        },
                        '&::-webkit-scrollbar-thumb': {
                            backgroundColor: '#ccc',
                            borderRadius: '4px',
                        },
                    }}>
                        {groupedWorkOrders[date].map((order) => (
                            <Box
                                key={order.id}
                                sx={{
                                    minWidth: 150,
                                    height: 180,
                                    border: '1px solid #ccc',
                                    display: 'flex',
                                    flexDirection: 'column',
                                    justifyContent: 'space-between',
                                    alignItems: 'center',
                                    padding: 2,
                                    borderRadius: 2,
                                    backgroundColor: '#f9f9f9'
                                }}
                            >
                                <Typography variant="body2" sx={{ mb: 2 }}>
                                    PDF #{order.id}
                                </Typography>
                                <Button
                                    variant="contained"
                                    size="small"
                                    onClick={() => handleDownload(order.id)}
                                >
                                    Download
                                </Button>
                            </Box>
                        ))}
                    </Box>
                </Box>
            ))}
        </Box>
    );
};

export default InspectorAssignedWork;
